package com.catpuzzle.assistant; import android.graphics.Bitmap; public final class FrameStore{private FrameStore(){} public static volatile Bitmap latest; public static volatile boolean captureReady=false; public static synchronized void set(Bitmap b){Bitmap o=latest;latest=b;if(o!=null&&o!=b&&!o.isRecycled())o.recycle();captureReady=b!=null;} public static synchronized Bitmap copy(){return latest==null?null:latest.copy(Bitmap.Config.ARGB_8888,false);}}